        }

        long[] invFact = new long[n + 1];
        invFact[n] = modInv(fact[n], MOD);
        for (int i = n - 1; i >= 0; i--) {
            invFact[i] = invFact[i + 1] * (i + 1) % MOD;
        }

        int left = 0;
        int right = n;
        int less = 0;
        int greater = 0;

        while (left < right) {
            int mid = (left + right) / 2;
            if (mid == pos) {
                left = mid + 1;
            } else if (mid < pos) {
                less++;
                left = mid + 1;
            } else {
                greater++;
                right = mid;
            }
        }

        int availableLess = x - 1;
        int availableGreater = n - x;

        if (less > availableLess || greater > availableGreater) {
            System.out.println(0);
            return;
        }

        long waysLess = C(availableLess, less, fact, invFact);
        long waysGreater = C(availableGreater, greater, fact, invFact);

        long result = waysLess * waysGreater % MOD;
        result = result * fact[less] % MOD;
        result = result * fact[greater] % MOD;
        result = result * fact[n - 1 - less - greater] % MOD;

        System.out.println(result);
    }

    static long C(int n, int k, long[] fact, long[] invFact) {
        if (k < 0 || k > n) return 0;
        return fact[n] * invFact[k] % MOD * invFact[n - k] % MOD;
    }

    static long modInv(long a, long mod) {
        return pow(a, mod - 2, mod);
    }

    static long pow(long a, long p, long mod) {
        long res = 1;
        a %= mod;
        while (p > 0) {
            if ((p & 1) == 1) res = res * a % mod;
            a = a * a % mod;
            p >>= 1;
        }
        return res;
    }

    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1024];
        private int ptr = 0;
        private int buflen = 0;

        private boolean hasNextByte() throws IOException {
            if (ptr < buflen) return true;
            else {
                ptr = 0;
                buflen = in.read(buffer);
                return buflen > 0;
            }
        }

        private int readByte() throws IOException {
            if (ptr < buflen) return buffer[ptr++];
            else {
                buflen = in.read(buffer);
                ptr = 0;
                return buflen > 0 ? buffer[ptr++] : -1;
            }
        }

        private static boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public int nextInt() {
            try {
                int c = readByte();
                while (isSpaceChar(c)) c = readByte();
                boolean minus = false;
                if (c == '-') {
                    minus = true;
                    c = readByte();
                }
                int res = 0;
                do {
                    res = res * 10 + c - '0';
                    c = readByte();
                } while (!isSpaceChar(c));
                return minus ? -res : res;
            } catch (IOException e) {
                throw new InputMismatchException();
            }
        }
    }
}
